import assert from 'node:assert/strict';

function readPose({id,selector='.nw-motion-dialog iframe',gid,progress}){
 const f=document.querySelector(selector),d=f.contentDocument,n=d.querySelector('[data-id="'+id+'"]'),clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id];if(progress!=null)clock.set(progress);
 return {vars:['z','rx','ry','rot'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),base:[n.style.left,n.style.top,n.style.width,n.style.getPropertyValue('--rot')],progress:clock.progress()};
}
export async function runMotionRetimeSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),factory:NAGWEB_MOTION_LAB.create().scene.elements}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.im-hov[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function select(id){const f=await frame(),n=await f.$(id?'[data-id="'+id+'"]':'.im-hov');await n.focus();await page.keyboard.press('Space');return n.evaluate(n=>n.dataset.id);}
  async function points(){const list=await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>({id:n.value,at:parseFloat(n.textContent)})));assert.deepEqual(await page.$$eval('[data-motion-key-jump]',ns=>ns.map(n=>({id:n.dataset.motionKeyJump,at:parseFloat(n.textContent)}))),list);return list;}
  async function move(value){await page.$eval('[data-motion-key-at]',(n,v)=>{n.value=String(v);n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function pose(id,progress){return page.evaluate(readPose,{id,progress});}
  await page.click('.tb-left [data-motion-open]');assert.equal(await page.$eval('[data-motion-key-at]',n=>n.disabled),true);const id=await select(),original=await points(),key=original.find(k=>k.at===35).id;await page.select('[data-motion-key]',key);
  await page.$eval('[data-motion-key-property="rotate"]',n=>{n.value='12';n.dispatchEvent(new Event('change',{bubbles:true}));});await page.select('[data-motion-key-ease]','linear');const initial=await pose(id,.35);assert.deepEqual(initial.vars,['0.00px','0.00deg','0.00deg','12.00deg']);
  const iframe=await page.$('.nw-motion-dialog iframe');await iframe.evaluate(f=>f.dataset.retimeProbe='unchanged');
  await page.click('[data-motion-key-at]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type('45');await page.keyboard.press('Tab');
  assert.deepEqual((await points()).map(k=>k.at),[0,45,65,100]);assert.equal(await page.$eval('[data-motion-key]',n=>n.value),key);assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'45');assert.ok(Math.abs((await pose(id)).progress-.45)<1e-12);assert.equal(await iframe.evaluate(f=>f.dataset.retimeProbe),'unchanged');
  const moved=await pose(id,.35),t=35/45,ease=1-4*(1-t)**3;assert.deepEqual(moved.vars,[(-320*(1-ease)).toFixed(2)+'px',(32*(1-ease)).toFixed(2)+'deg',(-40*(1-ease)).toFixed(2)+'deg',(12*ease).toFixed(2)+'deg'],'Retiming changes the actual interpolated pose');assert.deepEqual(moved.base,initial.base);
  await move(80);assert.deepEqual((await points()).map(k=>k.at),[0,65,80,100]);assert.equal(await page.$eval('[data-motion-key]',n=>n.value),key);assert.equal(await page.$eval('[data-motion-key-ease]',n=>n.value),'linear');assert.equal(await page.$eval('[data-motion-key-property="rotate"]',n=>n.valueAsNumber),12);
  const ordered=await points(),currentPose=await pose(id);for(const value of [65,65.04,100,0,-5,105,'']){await move(value);assert.equal(await page.$eval('[data-motion-key-at]',n=>n.valueAsNumber),80);assert.deepEqual(await points(),ordered);assert.deepEqual(await pose(id),currentPose);assert.ok(await page.$eval('[data-motion-key-status]',n=>n.textContent.length)>0,'Rejected position has an inline explanation');}
  await move(80.34);assert.deepEqual((await points()).map(k=>k.at),[0,65,80.3,100]);assert.equal(await page.$eval('[data-motion-key-at]',n=>n.value),'80.3');assert.equal(await page.$eval('[data-motion-key-status]',n=>n.textContent),'');const preparedPoints=await points();
  await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected'),{},id);assert.deepEqual(await points(),preparedPoints);assert.equal(await page.$eval('[data-motion-key-at]',n=>n.value),'80.3');
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(id=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),element:sec().elements.find(e=>e.id===id),images:sec().elements.filter(e=>e.type==='image')}),id);
  function expected(at){return before.factory[0].sdKeyframes.map(k=>({...k,id:original.find(p=>p.at===k.at).id,...(k.at===35?{at,rotate:12,ease:'linear'}:{})})).sort((a,b)=>a.at-b.at);}
  assert.deepEqual(inserted.element.sdKeyframes,expected(80.3));const strip=ks=>ks.map(({id,...k})=>k);for(let i=1;i<3;i++)assert.deepEqual(strip(inserted.images[i].sdKeyframes),strip(before.factory[i].sdKeyframes));
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select(id);await page.select('[data-motion-key]',key);assert.equal(await page.$eval('[data-motion-key-at]',n=>n.value),'80.3');await move(25);const savedPreview=await pose(id,.2);assert.deepEqual(savedPreview.vars,['-10.24px','1.02deg','-1.28deg','11.62deg']);await page.click('[data-motion-save]');const saved=await page.evaluate(id=>({project:JSON.stringify(project),element:sec().elements.find(e=>e.id===id),groups:sec().elements.filter(e=>e.nwMotionInstance).length}),id);assert.equal(saved.groups,1);const finalElement=structuredClone(inserted.element);finalElement.sdKeyframes=expected(25);assert.deepEqual(saved.element,finalElement);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select(id);await page.select('[data-motion-key]',key);await move(90);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='retime-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#retime-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.group.id);const exported=await page.evaluate(readPose,{id,selector:'#retime-export',gid:inserted.group.id,progress:.2});assert.deepEqual(exported.vars,savedPreview.vars);
  console.log('Reubicar momentos Motion Lab: campo real, interpolación visible, orden e IDs, pose/easing, decimales, colisiones/valores inválidos sin pérdida, borradores, guardar/cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#retime-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
